function fileCard(key,title,series=false){slots[key]={kind:series?'series':'spectrum',table:null,name:''};return '<fieldset class="qy-file-card" data-qy-slot="'+key+'"><legend>'+esc(title)+'</legend><label for="qy-file-'+key+'">Upload '+(series?'absorbance–emission pairs':'a numerical spectrum')+'</label><input type="file" id="qy-file-'+key+'" accept=".csv,.txt,.tsv,.dat,text/plain,text/csv"><details><summary>Or paste data</summary><label for="qy-text-'+key+'">'+(series?'Absorbance, integrated photon emission':'Wavelength, corrected intensity')+'</label><textarea id="qy-text-'+key+'" rows="3" placeholder="'+(series?'0.01,20&#10;0.02,40&#10;0.03,60':'350,0.1&#10;351,0.2&#10;…')+'"></textarea><button type="button" data-qy-read="'+key+'">Read pasted data</button></details><div class="color-fields two"><div><label for="qy-x-'+key+'">'+(series?'Absorbance column':'Wavelength column')+'</label><select id="qy-x-'+key+'" disabled></select></div><div><label for="qy-y-'+key+'">'+(series?'Photon-integral column':'Intensity column')+'</label><select id="qy-y-'+key+'" disabled></select></div>'+(series?'':'<div><label for="qy-unit-'+key+'">Wavelength / density unit</label><select id="qy-unit-'+key+'"><option value="nm">nm · intensity per nm</option><option value="um">µm · intensity per µm</option></select></div><div><label for="qy-baseline-'+key+'">Constant baseline · original units</label><input type="number" step="any" id="qy-baseline-'+key+'" value="0"></div><div><label for="qy-scale-'+key+'">Acquisition / calibration multiplier</label><input type="number" step="any" id="qy-scale-'+key+'" value="1"></div>')+'</div><p class="color-help qy-file-status" id="qy-file-status-'+key+'">No data loaded.</p></fieldset>';}
$('qy-sphere-files').innerHTML=fileCard('blank','Blue · matched blank / incident trace')+fileCard('sample','Red · directly illuminated sample');$('qy-relative-files').innerHTML=fileCard('rels','Unknown sample · emission')+fileCard('relr','Known standard · emission');$('qy-series-files').innerHTML=fileCard('seriess','Unknown sample · dilution pairs',true)+fileCard('seriesr','Known standard · dilution pairs',true);
function readTable(key,text,name){const table=Q.parse(text),s=slots[key];s.table=table;s.name=name;for(const a of ['x','y']){const select=$('qy-'+a+'-'+key);select.innerHTML=table.headers.map((h,i)=>'<option value="'+i+'">'+esc(h)+'</option>').join('');select.disabled=false;} $('qy-x-'+key).value='0';$('qy-y-'+key).value='1';$('qy-file-status-'+key).textContent=name+' · '+table.rows.length.toLocaleString()+' numeric rows · '+table.skipped+' text rows skipped.';invalidate(methodOf[key]);}
