document.querySelectorAll('[data-qy-read]').forEach(b=>b.addEventListener('click',guard(methodOf[b.dataset.qyRead],()=>readTable(b.dataset.qyRead,$('qy-text-'+b.dataset.qyRead).value,'Pasted data'))));
function trace(key,clip=false){const s=slots[key];if(!s.table)throw Error('Load the '+({blank:'blank',sample:'sample',rels:'unknown emission',relr:'reference emission'}[key]||key)+' data first.');return Q.prepare(s.table.rows,{xcol:val('qy-x-'+key),ycol:val('qy-y-'+key),unit:$('qy-unit-'+key).value,baseline:val('qy-baseline-'+key),scale:val('qy-scale-'+key),clip});}
