function sigma(){const v=['qy-u0','qy-u1','qy-u2'].map(optional);if(v.every(x=>x===null))return null;if(v.some(x=>x===null))throw Error('Provide all three integral uncertainties, or leave all three blank.');return{incident:v[0],unabsorbed:v[1],emitted:v[2]};}
function sampleNodes(t,lo,hi){const pts=[[lo,Q.at(t,lo)],...t.points.filter(p=>p[0]>lo&&p[0]<hi),[hi,Q.at(t,hi)]];if(pts.length<1600)return pts;const out=[pts[0]],step=Math.ceil(pts.length/700);for(let i=1;i<pts.length-1;i+=step){let min=i,max=i;for(let j=i+1;j<Math.min(pts.length-1,i+step);j++){if(pts[j][1]<pts[min][1])min=j;if(pts[j][1]>pts[max][1])max=j;}for(const j of [...new Set([min,max])].sort((a,b)=>a-b))out.push(pts[j]);}out.push(pts.at(-1));return out;}
